          Your booking link
        </p>
        <p className="mb-3 font-mono text-sm text-foreground">{bookingUrl}</p>
        <div className="flex gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={handleCopy}
            disabled={!slug}
          >
            <Copy className="mr-1.5 h-3.5 w-3.5" aria-hidden="true" />
            Copy link
          </Button>
          {slug && (
            <Button
