export function StepStudioProfile({ studioId, onNext }: StepStudioProfileProps) {
  const supabase = createClient()
  const fileInputRef = useRef<HTMLInputElement>(null)
  const [isDragging, setIsDragging] = useState(false)
  const [logoPreview, setLogoPreview] = useState<string | null>(null)
  const [logoFile, setLogoFile] = useState<File | null>(null)
  const [saving, setSaving] = useState(false)

  const {
    register,
    handleSubmit,
    setValue,
    formState: { errors },
  } = useForm<Step1Values>({
    resolver: zodResolver(step1Schema),
    defaultValues: { timezone: 'America/New_York' },
  })

  function handleFileSelect(file: File) {
    if (file.size > 2 * 1024 * 1024) {
      toast.error('Logo must be under 2 MB')
      return
    }
    if (!['image/png', 'image/jpeg', 'image/svg+xml'].includes(file.type)) {
      toast.error('PNG, JPG, or SVG only')
      return
    }
    setLogoFile(file)
    const url = URL.createObjectURL(file)
    setLogoPreview(url)
    toast.success('Logo uploaded')
  }

  async function onSubmit(data: Step1Values) {
    setSaving(true)
    try {
      let logoUrl: string | null = null

      // Upload logo if provided
      if (logoFile && studioId) {
        const ext = logoFile.name.split('.').pop() ?? 'png'
        const path = `${studioId}/logo.${ext}`
        const { error: uploadError } = await supabase.storage
          .from('studio-assets')
          .upload(path, logoFile, { upsert: true })
        if (uploadError) throw uploadError

        const { data: urlData } = supabase.storage
          .from('studio-assets')
          .getPublicUrl(path)
        logoUrl = urlData.publicUrl
      }

      // Update studio
      if (studioId) {
        const { error } = await supabase
          .from('studios')
          .update({
            name: data.studioName,
            timezone: data.timezone,
            ...(logoUrl ? { logo_url: logoUrl } : {}),
          })
          .eq('id', studioId)
        if (error) throw error
      }

      onNext()
    } catch (err) {
      toast.error(
        `Couldn't save — ${err instanceof Error ? err.message : 'Unknown error'}`,
      )
    } finally {
      setSaving(false)
    }
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
      <div>
        <Typography variant="h1" as="h2">
          Let&#39;s set up your studio
        </Typography>
        <p className="mt-1 text-sm text-muted-foreground">
          Your public booking page goes live in under 2 minutes
        </p>
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="studioName">
          Studio name <span className="text-destructive">*</span>
        </Label>
        <Input
          id="studioName"
          placeholder="Dark Matter Tattoo"
          autoComplete="organization"
          aria-describedby={errors.studioName ? 'studioName-error' : undefined}
          aria-invalid={!!errors.studioName}
          {...register('studioName')}
        />
        {errors.studioName && (
          <p id="studioName-error" role="alert" className="text-xs text-destructive">
            {errors.studioName.message}
          </p>
        )}
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="timezone">
          Timezone <span className="text-destructive">*</span>
        </Label>
        <Select
          defaultValue="America/New_York"
          onValueChange={(v) => { if (v !== null) setValue('timezone', v) }}
        >
          <SelectTrigger id="timezone">
            <SelectValue placeholder="Select timezone" />
          </SelectTrigger>
          <SelectContent>
            {TIMEZONES.map((tz) => (
              <SelectItem key={tz} value={tz}>
                {tz}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {errors.timezone && (
          <p role="alert" className="text-xs text-destructive">
            {errors.timezone.message}
          </p>
        )}
      </div>

      <div className="space-y-1.5">
        <Label>Studio logo (optional)</Label>
        <div
          role="button"
          tabIndex={0}
          aria-label="Upload studio logo"
          className={[
            'cursor-pointer rounded-lg border-2 border-dashed p-6 text-center transition-colors',
            isDragging
              ? 'border-primary/60 bg-primary/[0.04]'
              : 'border-border hover:border-primary/40',
          ].join(' ')}
          onClick={() => fileInputRef.current?.click()}
          onKeyDown={(e) => e.key === 'Enter' && fileInputRef.current?.click()}
          onDragOver={(e) => {
            e.preventDefault()
            setIsDragging(true)
          }}
          onDragLeave={() => setIsDragging(false)}
          onDrop={(e) => {
            e.preventDefault()
            setIsDragging(false)
            const file = e.dataTransfer.files[0]
            if (file) handleFileSelect(file)
          }}
        >
          {logoPreview ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={logoPreview}
              alt="Logo preview"
              className="mx-auto h-16 w-16 rounded object-contain"
            />
          ) : (
            <>
              <Upload
                className="mx-auto mb-2 h-6 w-6 text-muted-foreground/50"
                aria-hidden="true"
              />
              <p className="text-sm text-muted-foreground">
                Drop your logo here or browse
              </p>
              <p className="mt-0.5 text-xs text-muted-foreground/60">
                PNG, JPG or SVG · Max 2MB
              </p>
            </>
          )}
        </div>
        <input
          ref={fileInputRef}
          type="file"
          accept="image/png,image/jpeg,image/svg+xml"
          className="sr-only"
          onChange={(e) => {
            const file = e.target.files?.[0]
            if (file) handleFileSelect(file)
          }}
        />
      </div>

      <div className="flex justify-end pt-2">
        <Button type="submit" disabled={saving}>
          {saving ? 'Saving...' : 'Continue →'}
        </Button>
      </div>
    </form>
  )
}

'use client'

import { useState } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { toast } from 'sonner'
import { createClient } from '@/lib/supabase/client'
import { Typography } from '@/components/ui/typography'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'

const step2Schema = z.object({
  locationName: z.string().min(2, 'At least 2 characters').max(60),
  address: z.string().min(5, 'Enter a street address'),
  city: z.string().min(2, 'Required'),
  state: z.string().min(2, 'Required'),
  country: z.string().min(2, 'Required'),
  zip: z.string().min(3, 'Required'),
  phone: z.string().optional(),
})

type Step2Values = z.infer<typeof step2Schema>

interface StepFirstLocationProps {
  studioId: string | null
  onNext: () => void
  onBack: () => void
  onSkip: () => void
}

export function StepFirstLocation({
  studioId,
  onNext,
  onBack,
  onSkip,
}: StepFirstLocationProps) {
  const supabase = createClient()
  const [saving, setSaving] = useState(false)
  const [skipping, setSkipping] = useState(false)

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<Step2Values>({
    resolver: zodResolver(step2Schema),
    defaultValues: {
      locationName: 'Main Studio',
      country: 'United States',
    },
  })

  async function onSubmit(data: Step2Values) {
    setSaving(true)
    try {
      if (!studioId) throw new Error('No studio found')

      const { error } = await supabase.from('locations').insert({
        studio_id: studioId,
        name: data.locationName,
        address: data.address,
        city: data.city,
        state: data.state,
        country: data.country,
      })
      if (error) throw error

      onNext()
    } catch (err) {
      toast.error(
        `Couldn't save — ${err instanceof Error ? err.message : 'Unknown error'}`,
      )
    } finally {
      setSaving(false)
    }
  }

  async function handleSkip() {
    if (!studioId) {
      toast.error('Studio not found. Please refresh and try again.')
      return
    }
    setSkipping(true)
    try {
      const { error } = await supabase.from('locations').insert({
        studio_id: studioId,
        name: 'Main Studio',
      })
      if (error) throw error
      onSkip()
    } catch (err) {
      toast.error(
        `Couldn't skip — ${err instanceof Error ? err.message : 'Unknown error'}`,
      )
    } finally {
      setSkipping(false)
    }
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
      <div>
        <Typography variant="h1" as="h2">
          Where are you located?
        </Typography>
        <p className="mt-1 text-sm text-muted-foreground">
          You can add more locations later
        </p>
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="locationName">
          Location name <span className="text-destructive">*</span>
        </Label>
        <Input
          id="locationName"
          placeholder="Main Studio"
          {...register('locationName')}
          aria-invalid={!!errors.locationName}
        />
        {errors.locationName && (
          <p role="alert" className="text-xs text-destructive">{errors.locationName.message}</p>
        )}
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="address">
          Street address <span className="text-destructive">*</span>
        </Label>
        <Input
          id="address"
          autoComplete="street-address"
          {...register('address')}
          aria-invalid={!!errors.address}
        />
        {errors.address && (
          <p role="alert" className="text-xs text-destructive">{errors.address.message}</p>
        )}
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div className="space-y-1.5">
          <Label htmlFor="city">
            City <span className="text-destructive">*</span>
          </Label>
          <Input
            id="city"
            autoComplete="address-level2"
            {...register('city')}
            aria-invalid={!!errors.city}
          />
          {errors.city && (
            <p role="alert" className="text-xs text-destructive">{errors.city.message}</p>
          )}
        </div>
        <div className="space-y-1.5">
          <Label htmlFor="state">
            State <span className="text-destructive">*</span>
          </Label>
          <Input
            id="state"
            autoComplete="address-level1"
            {...register('state')}
            aria-invalid={!!errors.state}
          />
          {errors.state && (
            <p role="alert" className="text-xs text-destructive">{errors.state.message}</p>
          )}
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div className="space-y-1.5">
          <Label htmlFor="country">
            Country <span className="text-destructive">*</span>
          </Label>
          <Input
            id="country"
            autoComplete="country-name"
            {...register('country')}
            aria-invalid={!!errors.country}
          />
          {errors.country && (
            <p role="alert" className="text-xs text-destructive">{errors.country.message}</p>
          )}
        </div>
        <div className="space-y-1.5">
          <Label htmlFor="zip">
            Zip <span className="text-destructive">*</span>
          </Label>
          <Input
            id="zip"
            autoComplete="postal-code"
            {...register('zip')}
            aria-invalid={!!errors.zip}
          />
          {errors.zip && (
            <p role="alert" className="text-xs text-destructive">{errors.zip.message}</p>
          )}
        </div>
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="phone">Phone (optional)</Label>
        <Input
          id="phone"
          type="tel"
          autoComplete="tel"
          {...register('phone')}
        />
      </div>

      <div className="flex items-center justify-between pt-2">
        <Button type="button" variant="ghost" onClick={onBack}>
          ← Back
        </Button>
        <div className="flex items-center gap-3">
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="text-muted-foreground"
            disabled={skipping || saving}
            onClick={handleSkip}
          >
            {skipping ? 'Skipping...' : 'Skip for now'}
          </Button>
          <Button type="submit" disabled={saving || skipping}>
            {saving ? 'Saving...' : 'Continue →'}
          </Button>
        </div>
      </div>
    </form>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { slugify } from '@/lib/utils'

interface SlugPreviewProps {
  studioName: string
}

export function SlugPreview({ studioName }: SlugPreviewProps) {
  const [debouncedSlug, setDebouncedSlug] = useState(() => slugify(studioName))

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSlug(slugify(studioName))
    }, 200)
    return () => clearTimeout(timer)
  }, [studioName])

  const isEmpty = !studioName.trim()

  return (
    <p
      className="mt-2 flex items-center overflow-hidden"
      aria-live="polite"
      aria-label={
        isEmpty
          ? 'Booking URL preview: book.inkos.app/your-studio-name'
          : `Your booking URL: book.inkos.app/${debouncedSlug}`
      }
    >
      <span className="font-mono text-xs text-stone leading-none whitespace-nowrap shrink-0">
        book.inkos.app/
      </span>
      {isEmpty ? (
        <span className="font-serif italic text-xs text-stone leading-none overflow-hidden text-ellipsis max-w-[calc(100%-9rem)]">
          your-studio-name
        </span>
      ) : (
        <span className="font-mono text-xs font-medium text-onyx leading-none overflow-hidden text-ellipsis max-w-[calc(100%-9rem)]">
          {debouncedSlug}
        </span>
      )}
    </p>
  )
}

